"""Patch scenes/Touch_Game_demo_anim.tscn (as generated by tools/port/gen_godot.py) into the
wide-screen character-select scene:

  1. background  -> main_BG_2_wide.png (same scale/position, the original stays in the middle)
  2. "Olivia" watermark flow -> extra copies along the same diagonal lines + same motion tracks
  3. the BG animation is split: watermark flow keeps looping; the entrance (avatar, name, stars,
     skill panels) and the character-list slide-in become one-shot animations on their own players
  4. characters_list -> Node2D + CharacterSelect script with one clickable Sprite2D per panel
     (pieces sliced by tools/expand/slice_panels.py, placed exactly where the single image was)

Idempotent: refuses to run twice on the same file. Run from the project root:
  python tools/expand/apply_expansion.py
"""
import json
import re
import sys

SCENE = sys.argv[1] if len(sys.argv) > 1 else "scenes/Touch_Game_demo_anim.tscn"
PANELS = "assets/textures/char_panels/panels.json"
BG_PAD = 840  # must match extend_bg.py
MARKER = "; expanded by tools/expand/apply_expansion.py"

src = open(SCENE, encoding="utf-8").read()
if MARKER in src:
    print("already expanded:", SCENE)
    sys.exit(0)

# ---------------------------------------------------------------- resources
ext_ids = re.findall(r'\[ext_resource [^\]]*id="([^"]+)"\]', src)
next_id = max(int(i.split("_")[1]) for i in ext_ids) + 1
sub_ids = re.findall(r'\[sub_resource [^\]]*id="([^"]+)"\]', src)
next_id = max(next_id, max(int(i.split("_")[1]) for i in sub_ids) + 1)


def new_id(prefix):
    global next_id
    i = "%s_%d" % (prefix, next_id)
    next_id += 1
    return i


ext_lines = []


def add_ext(rtype, path):
    i = new_id({"Texture2D": "Texture", "Script": "Script", "Shader": "Shader"}[rtype])
    ext_lines.append('[ext_resource type="%s" path="%s" id="%s"]' % (rtype, path, i))
    return i


bg_wide = add_ext("Texture2D", "res://assets/textures/main_BG_2_wide.png")
sel_script = add_ext("Script", "res://scripts/character_select.gd")
outline = add_ext("Shader", "res://shaders/panel_outline.gdshader")
panels = json.load(open(PANELS))
panel_tex = [add_ext("Texture2D", "res://assets/textures/char_panels/" + p["file"]) for p in panels["panels"]]

# insert ext resources after the last existing one
last_ext = list(re.finditer(r'\[ext_resource [^\]]*\]\n', src))[-1]
src = src[:last_ext.end()] + "\n".join(ext_lines) + "\n" + src[last_ext.end():]

# ---------------------------------------------------------------- background
bg_old = re.search(r'\[node name="BG" type="Sprite2D" parent="BG_all"\]\n(?:.*\n)*?offset = Vector2\((-?[\d.]+), (-?[\d.]+)\)', src)
assert bg_old, "BG node not found"
ox, oy = float(bg_old.group(1)), float(bg_old.group(2))
bg_block = bg_old.group(0)
bg_new = re.sub(r'texture = ExtResource\("[^"]+"\)', 'texture = ExtResource("%s")' % bg_wide, bg_block)
bg_new = bg_new.replace("offset = Vector2(%s, %s)" % (bg_old.group(1), bg_old.group(2)), "offset = Vector2(%g, %g)" % (ox - BG_PAD, oy))
src = src.replace(bg_block, bg_new, 1)

# ---------------------------------------------------------------- animation split
anim_re = re.compile(r'\[sub_resource type="Animation" id="(\w+)"\]\nresource_name = "main_character_BG"\n(.*?)(?=\n\[sub_resource|\n\[node)', re.S)
m = anim_re.search(src)
assert m, "main_character_BG animation not found"
anim_id, body = m.group(1), m.group(2)
header_lines = []
track_chunks = {}
cur = None
for line in body.split("\n"):
    t = re.match(r'tracks/(\d+)/', line)
    if t:
        cur = int(t.group(1))
        track_chunks.setdefault(cur, []).append(line)
    elif cur is not None and line and not line.startswith("["):
        # continuation of the keys dictionary ("times": ..., "values": [...], "}")
        track_chunks[cur].append(line)
    else:
        header_lines.append(line)
tracks = []
for i in sorted(track_chunks):
    chunk = "\n".join(track_chunks[i])
    path = re.search(r'path = NodePath\("([^"]+)"\)', chunk).group(1)
    tracks.append((path, chunk))
print("tracks:", [p for p, _ in tracks])


def renumber(chunks):
    out = []
    for n, (_, chunk) in enumerate(chunks):
        out.append(re.sub(r'tracks/\d+/', "tracks/%d/" % n, chunk))
    return "\n".join(out)


def shifted_copy(chunk, new_path, dx, dy):
    chunk = re.sub(r'path = NodePath\("[^"]+"\)', 'path = NodePath("%s")' % new_path, chunk)

    def rep(mm):
        return "Vector2(%r, %r)" % (float(mm.group(1)) + dx, float(mm.group(2)) + dy)

    return re.sub(r'Vector2\((-?[\d.e+-]+), (-?[\d.e+-]+)\)', rep, chunk)


def track_length(chunk):
    times = re.search(r'"times": PackedFloat32Array\(([^)]*)\)', chunk).group(1)
    return max(float(t) for t in times.split(","))


by_path = dict(tracks)
# Watermark copies: the texts sit on two diagonal lines with step (778, -163); add copies so the
# wider view is covered through the whole loop.
WATERMARK_COPIES = [
    ("Olivia_1", "Olivia_1 (2)", 778.0, -163.0),   # right-moving line, right end
    ("Olivia_2", "Olivia_2 (2)", -778.0, 163.0),   # right-moving line, left end (enters from the left)
    ("Olivia_2 (1)", "Olivia_2 (3)", -778.0, 163.0),  # left-moving line, left end
]
flow_tracks = [(p, c) for p, c in tracks if p.startswith("Olivia_")]
for base, name, dx, dy in WATERMARK_COPIES:
    flow_tracks.append((name + ":position", shifted_copy(by_path[base + ":position"], name + ":position", dx, dy)))
list_tracks = [(p, c) for p, c in tracks if p.startswith("characters_list")]
entrance_tracks = [(p, c) for p, c in tracks if not p.startswith("Olivia_") and not p.startswith("characters_list")]
print("flow:", len(flow_tracks), "entrance:", len(entrance_tracks), "list:", len(list_tracks))

header = "\n".join(l for l in header_lines if l.strip())
flow_anim = '[sub_resource type="Animation" id="%s"]\nresource_name = "main_character_BG"\n%s\n%s' % (anim_id, header, renumber(flow_tracks))


def one_shot(name, chunks, rid):
    length = max(track_length(c) for _, c in chunks) + 0.05
    hdr = re.sub(r'^length = .*$', "length = %r" % length, header, flags=re.M)
    hdr = re.sub(r'^loop_mode = .*$', "loop_mode = 0", hdr, flags=re.M)
    return '[sub_resource type="Animation" id="%s"]\nresource_name = "%s"\n%s\n%s' % (rid, name, hdr, renumber(chunks))


entrance_id = new_id("Animation")
list_id = new_id("Animation")
entrance_lib = new_id("AnimationLibrary")
list_lib = new_id("AnimationLibrary")
entrance_anim = one_shot("entrance", entrance_tracks, entrance_id)
list_anim = one_shot("list_enter", list_tracks, list_id)
libs = (
    '[sub_resource type="AnimationLibrary" id="%s"]\n_data = {\n"entrance": SubResource("%s")\n}\n\n'
    '[sub_resource type="AnimationLibrary" id="%s"]\n_data = {\n"list_enter": SubResource("%s")\n}\n'
) % (entrance_lib, entrance_id, list_lib, list_id)
src = src[:m.start()] + flow_anim + "\n\n" + entrance_anim + "\n\n" + list_anim + "\n\n" + libs + src[m.end():]

# ---------------------------------------------------------------- watermark nodes
for base, name, dx, dy in WATERMARK_COPIES:
    nm = re.search(r'\[node name="%s" type="Sprite2D" parent="BG_all"\]\n(?:.+\n)+' % re.escape(base), src)
    assert nm, base
    block = nm.group(0)
    pm = re.search(r'position = Vector2\((-?[\d.]+), (-?[\d.]+)\)', block)
    copy = block.replace('name="%s"' % base, 'name="%s"' % name, 1)
    copy = copy.replace(pm.group(0), "position = Vector2(%r, %r)" % (float(pm.group(1)) + dx, float(pm.group(2)) + dy))
    src = src[:nm.end()] + copy + src[nm.end():]

# ---------------------------------------------------------------- character list node
cl = re.search(r'\[node name="characters_list" type="Sprite2D" parent="BG_all"\]\n(?:.+\n)+', src)
assert cl, "characters_list node not found"
block = cl.group(0)
pos = re.search(r'position = Vector2\(([^)]*)\)', block).group(1)
scale = re.search(r'scale = Vector2\(([^)]*)\)', block).group(1)
off = re.search(r'offset = Vector2\((-?[\d.]+), (-?[\d.]+)\)', block)
offx, offy = float(off.group(1)), float(off.group(2))
lines = [
    '[node name="characters_list" type="Node2D" parent="BG_all"]',
    "position = Vector2(%s)" % pos,
    "scale = Vector2(%s)" % scale,
    "z_index = 0",
    "z_as_relative = false",
    'script = ExtResource("%s")' % sel_script,
    'entrance_player = NodePath("../EntrancePlayer")',
    'background = NodePath("../BG")',
    "arrow_left_px = Vector2(%d, 515)" % (50 + BG_PAD),
    "arrow_right_px = Vector2(%d, 515)" % (663 + BG_PAD),
    "default_selection = 0",
    'outline_shader = ExtResource("%s")' % outline,
    "",
]
for p, tex in zip(panels["panels"], panel_tex):
    lines += [
        '[node name="%s" type="Sprite2D" parent="BG_all/characters_list"]' % p["file"].replace(".png", "").replace("panel_", "Panel_"),
        "position = Vector2(%r, %r)" % (p["cx"] + offx, p["cy"] + offy),
        'texture = ExtResource("%s")' % tex,
        "metadata/empty = %s" % ("true" if p["empty"] else "false"),
        "",
    ]
src = src.replace(block, "\n".join(lines), 1)

# ---------------------------------------------------------------- animation players
players = (
    '[node name="EntrancePlayer" type="AnimationPlayer" parent="BG_all"]\n'
    'libraries = {\n"": SubResource("%s")\n}\nautoplay = "entrance"\n\n'
    '[node name="ListPlayer" type="AnimationPlayer" parent="BG_all"]\n'
    'libraries = {\n"": SubResource("%s")\n}\nautoplay = "list_enter"\n\n'
) % (entrance_lib, list_lib)
ap = src.index('[node name="AnimationPlayer" type="AnimationPlayer" parent="BG_all"]')
src = src[:ap] + players + src[ap:]

# ---------------------------------------------------------------- header
steps = len(re.findall(r'\[ext_resource ', src)) + len(re.findall(r'\[sub_resource ', src)) + 1
src = re.sub(r'^\[gd_scene load_steps=\d+ format=3\]', "[gd_scene load_steps=%d format=3]\n%s" % (steps, MARKER), src, count=1, flags=re.M)
open(SCENE, "w", encoding="utf-8", newline="\n").write(src)
print("patched", SCENE)
